using System;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEngine;
static class Program {
 static int passed,failed;
 static readonly BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Assert(bool condition,string message){if(!condition)throw new Exception(message);}
 static object Call(object value,string method)=>value.GetType().GetMethod(method,Private).Invoke(value,null);
 static void Set(object value,string name,object data){var f=value.GetType().GetField(name,Private);if(f!=null)f.SetValue(value,data);else value.GetType().GetProperty(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).SetValue(value,data);}
 static object Get(object value,string name)=>value.GetType().GetField(name,Private).GetValue(value);
 static void StaticSession(SurvivalSession s)=>typeof(SurvivalSession).GetProperty("Instance").SetValue(null,s);
 class Match {
  public readonly PlayerHealth Player=new PlayerHealth{transform=new Transform{position=new Vector3(1,2,3)}};
  public readonly GunSystem Gun=new GunSystem();public readonly RoundManager Rounds=new RoundManager();public readonly PlayerController Movement=new PlayerController{transform=new Transform()};
  public readonly SurvivalSession Session=new SurvivalSession();public readonly SaveSystem Saves=new SaveSystem();public readonly Database Db;
  public Match(){Time.timeScale=1;Time.time=Time.unscaledTime=0;Time.deltaTime=1;PlayerPrefs.Values.Clear();Input.KeysDown.Clear();Input.MouseHeld.Clear();Input.MouseDown.Clear();Physics.NextHits=new RaycastHit[0];UnityEngine.Random.value=1;Time.frameCount=0;UnityEngine.Object.ResetSimulation();Camera.main=null;SaveSystem.instance=null;StaticSession(null);typeof(WorldProgression).GetProperty("Instance").SetValue(null,null);Application.persistentDataPath=Path.Combine(Environment.GetEnvironmentVariable("ZOMBIES_TEST_DATA") ?? Path.GetTempPath(),Guid.NewGuid().ToString("N"));Db=new Database();var body=new GameObject("Player"){tag="Player"};body.transform.position=new Vector3(1,2,3);body.AttachForTest(Player);body.AttachForTest(Movement);new GameObject("Weapon").AttachForTest(Gun);Player.InitNewGame();Gun.player=Player;Call(Gun,"Awake");new GameObject("Session").AttachForTest(Session);Set(Session,"Player",Player);Set(Session,"Gun",Gun);Set(Session,"Rounds",Rounds);Set(Session,"Movement",Movement);StaticSession(Session);Set(Saves,"db",Db);SaveSystem.instance=Saves;UnityEngine.Object.Registry[typeof(PlayerHealth)]=Player;UnityEngine.Object.Registry[typeof(GunSystem)]=Gun;UnityEngine.Object.Registry[typeof(RoundManager)]=Rounds;UnityEngine.Object.Registry[typeof(PlayerController)]=Movement;UnityEngine.Object.Registry[typeof(SaveSystem)]=Saves;}
  public void Shop(int points=10000){Session.ApplySavedProgress(new GameState{points=points});Rounds.inIntermission=true;Set(Session,"IsShopOpen",true);Time.timeScale=0;}
  public void SaveTick(float time){Time.unscaledTime=time;Call(Saves,"Update");}
  public void Advance(float seconds){Time.unscaledDeltaTime=seconds;Time.deltaTime=seconds*Time.timeScale;Time.unscaledTime+=seconds;Time.time+=Time.deltaTime;Time.frameCount++;Call(Session,"Update");}
  public WorldProgression MakeWorld(){var camera=new GameObject("Player camera").AddComponent<Camera>();camera.transform.position=Player.transform.position+Vector3.up*1.25f;camera.transform.SetParent(Player.transform,false);Camera.main=camera;Gun.playerCam=camera;return new GameObject("World progression").AddComponent<WorldProgression>();}
  public WorldInteraction Station(WorldProgression world,WorldInteraction.InteractionKind kind,float distance=2f){var station=new GameObject(kind.ToString()).AddComponent<WorldInteraction>();station.transform.position=Player.transform.position+Vector3.forward*distance;station.Configure(world,kind,kind.ToString());return station;}

 }
 static void Test(string name,Action body){try{body();Console.WriteLine("PASS "+name);passed++;}catch(Exception e){Console.WriteLine("FAIL "+name+": "+(e.InnerException??e));failed++;}}
 static ZombieAI Enemy(Match match,ZombieArchetype kind,bool skeleton=false){
  var go=new GameObject("Enemy "+kind){layer=6};go.transform.position=match.Player.transform.position+Vector3.forward*5;
  var collider=go.AddComponent<CapsuleCollider>();collider.bounds=new Bounds(go.transform.position+Vector3.up*1.5f,new Vector3(1,3,1));
  var agent=go.AddComponent<UnityEngine.AI.NavMeshAgent>();agent.isOnNavMesh=true;go.AddComponent<Animator>();
  if(skeleton){
   string[] names={"Hips","Spine","Neck","Head","LeftArm","LeftForeArm","LeftHand","RightArm","RightForeArm","RightHand","LeftUpLeg","LeftLeg","LeftFoot","RightUpLeg","RightLeg","RightFoot"};
   int[] parents={-1,0,1,2,1,4,5,1,7,8,0,10,11,0,13,14};
   Vector3[] points={new Vector3(0,.9f,0),new Vector3(0,1.3f,0),new Vector3(0,1.7f,0),new Vector3(0,1.9f,0),new Vector3(-.3f,1.5f,0),new Vector3(-.65f,1.4f,0),new Vector3(-.9f,1.35f,0),new Vector3(.3f,1.5f,0),new Vector3(.65f,1.4f,0),new Vector3(.9f,1.35f,0),new Vector3(-.18f,.8f,0),new Vector3(-.18f,.4f,0),new Vector3(-.18f,.05f,.1f),new Vector3(.18f,.8f,0),new Vector3(.18f,.4f,0),new Vector3(.18f,.05f,.1f)};
   var bones=new Transform[names.Length];for(int i=0;i<names.Length;i++){bones[i]=new GameObject("Zombie_"+names[i]){layer=6}.transform;bones[i].SetParent(parents[i]<0?go.transform:bones[parents[i]],false);bones[i].position=go.transform.position+points[i];}
   var renderer=new GameObject("Skin").AddComponent<SkinnedMeshRenderer>();renderer.transform.SetParent(go.transform,false);renderer.bones=bones;
  }
  var zombie=go.AttachForTest(new ZombieAI{archetype=kind});Call(zombie,"Awake");zombie.InitializeForRound(1,match.Rounds);return zombie;
 }
 static int Main(){
 Test("Hit, body kill and headshot rewards update points and counters",()=>{var m=new Match();m.Session.RegisterShot();m.Session.RegisterHit(false,false);m.Session.RegisterHit(true,false);m.Session.RegisterHit(true,true);Assert(m.Session.Points==670&&m.Session.Kills==2&&m.Session.Headshots==1&&m.Session.Hits==3&&m.Session.ShotsFired==1,"Combat rewards differ");});
 Test("Economy rejects negative costs and insufficient funds atomically",()=>{var m=new Match();Assert(!m.Session.TrySpend(-1)&&!m.Session.TrySpend(501)&&m.Session.Points==500,"Invalid purchase changed balance");Assert(m.Session.TrySpend(500)&&m.Session.Points==0,"Exact affordable purchase failed");});
 Test("Point rewards saturate rather than overflowing into negative balance",()=>{var m=new Match();m.Session.ApplySavedProgress(new GameState{points=int.MaxValue});m.Session.RegisterHit(true,true);Assert(m.Session.Points==int.MaxValue,"Reward overflowed balance");});
 Test("Purchases require both an open arsenal and an intermission",()=>{var m=new Match();m.Session.ApplySavedProgress(new GameState{points=10000});m.Session.BuyWeaponUpgrade();Assert(m.Session.Points==10000&&m.Session.WeaponTier==0,"Closed shop permitted upgrade");Set(m.Session,"IsShopOpen",true);m.Session.BuyWeaponUpgrade();Assert(m.Session.Points==10000,"Live wave permitted purchase");m.Rounds.inIntermission=true;m.Session.BuyWeaponUpgrade();Assert(m.Session.WeaponTier==1&&m.Session.Points==8500,"Legal upgrade failed");});
 Test("Three weapon tiers charge escalating costs and respect maximum tier",()=>{var m=new Match();m.Shop();for(int i=0;i<4;i++)m.Session.BuyWeaponUpgrade();Assert(m.Session.WeaponTier==3&&m.Session.Points==1000&&m.Session.DamageMultiplier==2.5f,"Weapon progression cap/cost failed");});
 Test("Health and quick-reload upgrades respect purchase limits",()=>{var m=new Match();m.Shop(10000);for(int i=0;i<3;i++)m.Session.BuyHealthUpgrade();Assert(m.Player.MaxHP==200&&m.Session.HealthBonus==100&&m.Session.Points==6000,"Health perk cap/cost failed");m.Session.BuyQuickReload();m.Session.BuyQuickReload();Assert(m.Session.HasQuickReload&&m.Session.ReloadMultiplier==.65f&&m.Session.Points==4500,"Reload perk purchased twice");});
 Test("Ammo purchase fills magazine and reserve without charging twice at capacity",()=>{var m=new Match();m.Shop(1000);m.Gun.currentAmmo=1;m.Gun.reserveAmmo=0;m.Session.BuyAmmo();Assert(m.Gun.currentAmmo==30&&m.Gun.reserveAmmo==300&&m.Session.Points==500,"Ammo purchase failed");m.Session.BuyAmmo();Assert(m.Session.Points==500,"Full ammo charged for no benefit");});
 Test("Reload transfers only missing ammunition and rejects overlapping reloads",()=>{var m=new Match();m.Gun.currentAmmo=23;m.Gun.reserveAmmo=9;Call(m.Gun,"BeginReload");Call(m.Gun,"BeginReload");Assert(m.Gun.IsReloading&&m.Gun.Coroutines.Count==1,"Duplicate reload coroutine");m.Gun.Coroutines[0].Tick();Assert(m.Gun.currentAmmo==30&&m.Gun.reserveAmmo==2&&!m.Gun.IsReloading,"Reload duplicated or lost ammo");});
 Test("Refill cancels pending reload before applying new ammunition",()=>{var m=new Match();m.Gun.currentAmmo=1;m.Gun.reserveAmmo=40;Call(m.Gun,"BeginReload");m.Gun.AddReserveAmmo(300,true);m.Gun.Coroutines[0].Tick();Assert(m.Gun.currentAmmo==30&&m.Gun.reserveAmmo==300&&!m.Gun.IsReloading,"Cancelled reload transferred ammo after refill");});
 Test("Saved ammunition and health are clamped to legal capacities",()=>{var m=new Match();m.Gun.ApplyLoadedGun("AK",999,-5);m.Player.ApplyLoadedHealth(999,150);Assert(m.Gun.currentAmmo==30&&m.Gun.reserveAmmo==0&&m.Player.CurrentHP==150&&m.Player.MaxHP==150,"Invalid loaded state bypassed limits");});
 Test("Burst save requests share a fixed debounce deadline and capture latest state",()=>{var m=new Match();m.Saves.BeginSession();float deadline=(float)Get(m.Saves,"saveAt");Time.unscaledTime=1;m.Gun.currentAmmo=24;m.Session.RegisterHit(true,true);m.Player.TakeDamage(15);m.Saves.RequestSave();Assert((float)Get(m.Saves,"saveAt")==deadline,"Burst pushed save deadline indefinitely");m.SaveTick(1.9f);Assert(!m.Db.HasSave(),"Debounced save wrote early");m.SaveTick(2f);var state=m.Db.LoadGame();Assert(state!=null&&state.vida==85&&state.ammo_carregador==24&&state.points==600&&state.pos_z==3,"Save snapshot stale or inconsistent");});
 Test("Game over stops waves, invalidates recovery and cannot recreate a dead save",()=>{var m=new Match();m.Saves.BeginSession();m.SaveTick(2);Assert(m.Db.HasSave(),"Initial living snapshot failed");m.Player.TakeDamage(100);Assert(m.Session.IsGameOver&&m.Rounds.IsStopped&&!m.Db.HasSave()&&Time.timeScale==0,"Game over not atomic");m.Saves.RequestSave();m.SaveTick(100);m.Session.EndGame();Assert(!m.Db.HasSave(),"Late autosave recreated dead run");int points=m.Session.Points;m.Session.RegisterHit(true,true);Assert(m.Session.Points==points&&!m.Session.TrySpend(1),"Ended run still changes economy");});
 Test("New game reset discards stale pending snapshots",()=>{var m=new Match();m.Saves.BeginSession();m.Saves.Save(50,"OLD",2,3,9,new Vector3(4,5,6));m.Saves.ResetForNewGame();m.SaveTick(100);Assert(!m.Db.HasSave(),"Reset wrote stale snapshot");});
 Test("Central loader restores full state and consumes load flag exactly once",()=>{var m=new Match();m.Db.SaveGame(new GameState{vida=80,ammo_carregador=17,ammo_reserva=87,round=8,pos_x=10,pos_y=2,pos_z=-7,has_position=1,points=2345,kills=20,headshots=5,weapon_tier=2,health_bonus=50,reload_perk=1});PlayerPrefs.SetInt("load",1);var loader=new GameLoader{gunSystem=m.Gun};Call(loader,"Start");Assert(!PlayerPrefs.HasKey("load")&&m.Player.MaxHP==150&&m.Player.CurrentHP==80&&m.Gun.currentAmmo==17&&m.Rounds.currentRound==8&&m.Movement.transform.position.x==10&&m.Session.Points==2345&&m.Session.WeaponTier==2,"Central restore missed state or perk order");m.Gun.currentAmmo=12;Call(loader,"Start");Assert(m.Gun.currentAmmo==12,"Loader applied state more than once");});
 Test("Escape closes the arsenal without opening pause in either Update order",()=>{for(int order=0;order<2;order++){var m=new Match();m.Shop();var pause=new PauseMenu();Input.KeysDown.Add(KeyCode.Escape);if(order==0){Call(m.Session,"Update");Call(pause,"Update");}else{Call(pause,"Update");Call(m.Session,"Update");}Assert(!m.Session.IsShopOpen&&Time.timeScale==1f&&!(bool)Get(pause,"isPaused"),"Escape was consumed twice in Update order "+order);}});
 Test("Health regeneration waits after damage and freezes during pause",()=>{var m=new Match();m.Player.TakeDamage(25);Time.time=6;Call(m.Player,"Update");Assert(m.Player.CurrentHP==75,"Health regenerated before the new recovery delay");Time.time=6.5f;Time.deltaTime=.5f;Call(m.Player,"Update");Assert(m.Player.CurrentHP==79,"Health regeneration rate incorrect");Time.timeScale=0;Time.time=10;Call(m.Player,"Update");Assert(m.Player.CurrentHP==79,"Health regenerated while paused");});
 Test("Double Points applies exactly twice to hits, kills and round bonuses without overflow",()=>{var m=new Match();m.Session.ActivatePowerUp(SurvivalPowerUp.DoublePoints);m.Session.RegisterHit(false,false);m.Session.RegisterHit(true,false);m.Session.RegisterHit(true,true);m.Session.OnRoundCompleted(1);Assert(m.Session.Points==1090,"Double points missed or duplicated a reward category");m.Session.AwardBonus(int.MaxValue);Assert(m.Session.Points==int.MaxValue&&m.Session.LastPointsAwarded==int.MaxValue,"Doubled reward overflowed");m.Session.AwardBonus(-1);Assert(m.Session.Points==int.MaxValue,"Negative bonus altered balance");});
 Test("Power-up deadlines use scaled time, refresh duration and clear on death",()=>{var m=new Match();m.Session.ActivatePowerUp(SurvivalPowerUp.DoublePoints);m.Session.ActivatePowerUp(SurvivalPowerUp.InstaKill);m.Advance(5);Assert(m.Session.DoublePointsRemaining==25&&m.Session.InstaKillRemaining==5,"Buff deadlines have wrong durations");Time.timeScale=0;m.Advance(100);Assert(m.Session.DoublePointsRemaining==25&&m.Session.InstaKillRemaining==5,"Paused time consumed a buff");Time.timeScale=1;m.Session.ActivatePowerUp(SurvivalPowerUp.DoublePoints);Assert(m.Session.DoublePointsRemaining==30,"Repeated pickup stacked rather than refreshing duration");m.Advance(5);Assert(!m.Session.InstaKillActive&&m.Session.DoublePointsRemaining==25,"Buff expiry is incorrect");m.Player.TakeDamage(100);Assert(!m.Session.DoublePointsActive&&!m.Session.InstaKillActive&&m.Session.DoublePointsRemaining==0,"Death retained buffs");});
 Test("Max Ammo cancels a partial reload without charging points",()=>{var m=new Match();m.Gun.currentAmmo=2;m.Gun.reserveAmmo=40;Call(m.Gun,"BeginReload");m.Session.ActivatePowerUp(SurvivalPowerUp.MaxAmmo);m.Gun.Coroutines[0].Tick();Assert(m.Gun.currentAmmo==30&&m.Gun.reserveAmmo==300&&!m.Gun.IsReloading&&m.Session.Points==500,"Max Ammo duplicated ammunition or charged points");});
 Test("World drops respect count cap, pause lifetime, expiry and game-over cleanup",()=>{var m=new Match();UnityEngine.Random.value=0;for(int i=0;i<5;i++)m.Session.TryDropPowerUp(new Vector3(20+i,2,20));Assert(m.Session.ActiveDropCount==3,"World drop cap exceeded");Time.timeScale=0;m.Advance(100);foreach(var drop in UnityEngine.Object.FindObjectsByType<PowerUpPickup>(FindObjectsSortMode.None))Call(drop,"Update");Assert(m.Session.ActiveDropCount==3,"Paused game consumed drop lifetime");Time.timeScale=1;m.Advance(26);foreach(var drop in UnityEngine.Object.FindObjectsByType<PowerUpPickup>(FindObjectsSortMode.None))Call(drop,"Update");Assert(m.Session.ActiveDropCount==0,"Expired drops remained registered");m.Session.TryDropPowerUp(new Vector3(float.NaN,2,3));Assert(m.Session.ActiveDropCount==0,"Invalid drop position was accepted");m.Session.TryDropPowerUp(new Vector3(20,2,20));Assert(m.Session.ActiveDropCount==1,"Expired slot was not reusable");m.Session.EndGame();Assert(m.Session.ActiveDropCount==0&&UnityEngine.Object.FindObjectsByType<PowerUpPickup>(FindObjectsSortMode.None).Length==0,"Game over left active drops");});
 Test("Nearby power-up cannot be collected through a wall",()=>{var m=new Match();var pickup=PowerUpPickup.Create(m.Session,SurvivalPowerUp.DoublePoints,m.Player.transform.position);var wall=new GameObject("Wall").AddComponent<BoxCollider>();Physics.NextHits=new[]{new RaycastHit{collider=wall,distance=.1f}};Call(pickup,"Update");Assert(!m.Session.DoublePointsActive&&pickup,"Wall did not block collection");Physics.NextHits=new RaycastHit[0];Call(pickup,"Update");Assert(m.Session.DoublePointsActive&&!pickup,"Reachable pickup was not consumed once");});
 Test("Saving and continuing restores world progression and elapsed time but not temporary buffs",()=>{var m=new Match();var world=m.MakeWorld();world.RestoreProgress(3,true);m.Session.ApplySavedProgress(new GameState{elapsed_seconds=100.5f});m.Session.ActivatePowerUp(SurvivalPowerUp.DoublePoints);m.Advance(7.5f);m.Saves.BeginSession();m.Saves.FlushSave();var snapshot=m.Db.LoadGame();Assert(snapshot!=null&&snapshot.unlocked_zones==3&&snapshot.power_enabled==1&&snapshot.elapsed_seconds==108,"World/time snapshot missing");var resumed=new Match();var resumedWorld=resumed.MakeWorld();resumed.Db.SaveGame(snapshot);PlayerPrefs.SetInt("load",1);Call(new GameLoader{gunSystem=resumed.Gun},"Start");Assert(resumedWorld.UnlockedZones==3&&resumedWorld.PowerEnabled&&resumed.Session.ElapsedSeconds==108&&!resumed.Session.DoublePointsActive,"Recovery did not restore world/time cleanly");resumed.Advance(2);Assert(resumed.Session.ElapsedSeconds==110,"Continued run lost elapsed time");});
 Test("Checkpoint and powered upgrades charge once and enforce their prerequisites",()=>{var m=new Match();m.Session.ApplySavedProgress(new GameState{points=10000});var world=m.MakeWorld();var church=m.Station(world,WorldInteraction.InteractionKind.ChurchGate);var village=m.Station(world,WorldInteraction.InteractionKind.VillageGate);var generator=m.Station(world,WorldInteraction.InteractionKind.GuardCheckpoint);var arsenal=m.Station(world,WorldInteraction.InteractionKind.WeaponUpgrade);Assert(!world.TryActivate(arsenal)&&m.Session.Points==10000,"Locked arsenal charged points");Time.frameCount++;Assert(world.TryActivate(church)&&m.Session.Points==9250&&world.UnlockedZones==1,"Church gate unlock failed");Time.frameCount++;Assert(!world.TryActivate(generator)&&m.Session.Points==9250,"Generator was activated before the village opened");Time.frameCount++;Assert(world.TryActivate(village)&&m.Session.Points==8000&&!world.PowerEnabled,"Village gate also powered the generator");Time.frameCount++;Assert(world.TryActivate(generator)&&world.PowerEnabled&&m.Session.Points==6750,"Power activation failed");Time.frameCount++;Assert(world.TryActivate(arsenal)&&m.Session.WeaponTier==1&&m.Session.Points==5250,"Powered arsenal upgrade failed");Time.frameCount++;Assert(!world.TryActivate(generator)&&m.Session.Points==5250,"Powered generator charged twice");});
 Test("One E press focuses only the nearest station and cannot double-charge in one frame",()=>{var m=new Match();m.Session.ApplySavedProgress(new GameState{points=10000});var world=m.MakeWorld();var first=m.Station(world,WorldInteraction.InteractionKind.ChurchGate,2);var second=m.Station(world,WorldInteraction.InteractionKind.VillageGate,2.3f);Input.KeysDown.Add(KeyCode.E);Call(world,"Update");Call(world,"Update");Assert(world.FocusedInteraction==first&&m.Session.Points==9250&&!world.PowerEnabled,"Multiple stations consumed the same key frame");Assert(!world.TryActivate(second)&&m.Session.Points==9250,"Direct activation bypassed same-frame guard");first.enabled=false;Time.frameCount++;Call(world,"Update");Assert(world.FocusedInteraction==second&&!world.PowerEnabled&&world.UnlockedZones==3&&m.Session.Points==8000,"Next gate could not activate separately on a later frame");});
 Test("Station interaction rejects occlusion and targets behind the camera",()=>{var m=new Match();m.Session.ApplySavedProgress(new GameState{points=10000});var world=m.MakeWorld();m.Station(world,WorldInteraction.InteractionKind.ChurchCheckpoint);Input.KeysDown.Add(KeyCode.E);var wall=new GameObject("Wall").AddComponent<BoxCollider>();Physics.NextHits=new[]{new RaycastHit{collider=wall,distance=1}};Call(world,"Update");Assert(world.FocusedInteraction==null&&m.Session.Points==10000,"Station was used through a wall");Physics.NextHits=new RaycastHit[0];Camera.main.transform.forward=-Vector3.forward;Time.frameCount++;Call(world,"Update");Assert(world.FocusedInteraction==null&&m.Session.Points==10000,"Station behind the player was used");});
 Test("World services reject paused, arsenal-open and ended runs",()=>{var m=new Match();m.Session.ApplySavedProgress(new GameState{points=10000});var world=m.MakeWorld();var church=m.Station(world,WorldInteraction.InteractionKind.ChurchCheckpoint);Time.timeScale=0;Assert(!world.TryActivate(church),"Paused run accepted world purchase");Time.timeScale=1;Set(m.Session,"IsShopOpen",true);Assert(!world.TryActivate(church),"UI arsenal permitted simultaneous world purchase");Set(m.Session,"IsShopOpen",false);m.Session.EndGame();Assert(!world.TryActivate(church)&&m.Session.Points==10000,"Ended run changed world progression");});
 Test("Rejected saved position preserves the actual scene spawn",()=>{var m=new Match();var world=m.MakeWorld();var initial=m.Movement.transform.position;m.Db.SaveGame(new GameState{has_position=1,pos_x=10000,pos_y=-500,pos_z=10000,unlocked_zones=3,power_enabled=1,elapsed_seconds=42});PlayerPrefs.SetInt("load",1);Call(new GameLoader{gunSystem=m.Gun},"Start");Assert(m.Movement.transform.position==initial&&m.Movement.transform.position!=Vector3.zero&&world.UnlockedZones==3&&m.Session.ElapsedSeconds==42,"Invalid save teleported the player or lost restored state");Assert(!world.IsPositionAllowed(new Vector3(float.NaN,0,0)),"NaN position accepted");});
 Test("Melee cancels reload, consumes no ammunition and blocks simultaneous held fire",()=>{var m=new Match();m.MakeWorld();Cursor.lockState=CursorLockMode.Locked;m.Gun.currentAmmo=23;m.Gun.reserveAmmo=9;Call(m.Gun,"BeginReload");Input.KeysDown.Add(KeyCode.V);Input.MouseHeld.Add(0);Call(m.Gun,"Update");Assert(m.Gun.IsMeleeing&&!m.Gun.IsReloading&&m.Gun.currentAmmo==23&&m.Gun.reserveAmmo==9&&m.Session.ShotsFired==0,"Melee fired or consumed reload ammo");Assert(!m.Gun.TryMelee(),"Melee ignored cooldown");Input.KeysDown.Clear();Time.time=.1f;Call(m.Gun,"Update");Assert(m.Gun.currentAmmo==23,"Gun fired during melee recovery");Time.time=.3f;Call(m.Gun,"Update");Assert(m.Gun.currentAmmo==22&&m.Session.ShotsFired==1,"Gun did not resume after melee recovery");Time.timeScale=0;Time.time=2;Assert(!m.Gun.TryMelee(),"Paused run allowed melee");});
 Test("Melee rewards do not inflate bullet accuracy statistics",()=>{var m=new Match();m.Session.RegisterShot();m.Session.RegisterHit(false,false);m.Session.RegisterHit(true,false,true);Assert(m.Session.ShotsFired==1&&m.Session.Hits==1&&m.Session.Kills==1&&m.Session.Points==640,"Melee was counted as a bullet hit");});
 Test("Weapon motion preserves authored local pose and restores its hierarchy on removal",()=>{var m=new Match();m.MakeWorld();var camera=m.Gun.playerCam.transform;var cameraPosition=camera.position;var model=new GameObject("WeaponHolder").transform;model.SetParent(camera,false);model.localPosition=new Vector3(.2f,-.3f,.8f);model.localScale=new Vector3(2,2,2);var original=model.localPosition;var motion=m.Gun.ViewMotion;motion.Initialize(m.Gun);Assert(motion.IsInitialized&&model.parent==motion.MotionPivot&&motion.MotionPivot.parent==camera&&model.localPosition==original&&model.localScale==new Vector3(2,2,2)&&camera.position==cameraPosition,"Motion wrapper changed the authored or camera pose");motion.ResetPose();UnityEngine.Object.Destroy(motion);Assert(model.parent==camera&&model.localPosition==original&&camera.position==cameraPosition,"Removing motion failed to restore model hierarchy");});
 Test("Reload animation curves return to their initial pose and remain continuous",()=>{Assert(WeaponViewMotion.MagazineWithdrawal(0)==0&&WeaponViewMotion.MagazineWithdrawal(1)==0&&WeaponViewMotion.MagazineWithdrawal(.5f)>.99f,"Magazine curve endpoints or withdrawal invalid");Assert(WeaponViewMotion.ReloadPoseWeight(0)==0&&WeaponViewMotion.ReloadPoseWeight(1)==0&&WeaponViewMotion.ReloadPoseWeight(.5f)>.99f,"Reload pose never returned to idle");float previousMagazine=0,previousPose=0;for(int i=0;i<=500;i++){float t=i/500f;float magazine=WeaponViewMotion.MagazineWithdrawal(t),pose=WeaponViewMotion.ReloadPoseWeight(t);Assert(magazine>=0&&magazine<=1&&pose>=0&&pose<=1&&Math.Abs(magazine-previousMagazine)<.1f&&Math.Abs(pose-previousPose)<.1f,"Reload curve jumped or left valid range");previousMagazine=magazine;previousPose=pose;}});
 Test("Automatic fire cannot extend a zombie stagger indefinitely",()=>{var m=new Match();var zombie=new GameObject("Zombie").AddComponent<ZombieAI>();zombie.InitializeForRound(1,m.Rounds);zombie.TakeDamage(1);float first=(float)Get(zombie,"staggerUntil");Time.time=.2f;zombie.TakeDamage(1);Assert((float)Get(zombie,"staggerUntil")==first,"Repeated bullets prolonged active stagger");Time.time=2;zombie.TakeDamage(1);Assert((float)Get(zombie,"staggerUntil")>2,"Stagger never recovered after cooldown");});
 Test("Zombie attack rejects another floor even when collider centres are close",()=>{var m=new Match();var playerCollider=m.Player.gameObject.AddComponent<CapsuleCollider>();playerCollider.bounds=new Bounds(new Vector3(0,2.3f,0),new Vector3(1,2,1));var body=new GameObject("Zombie");var collider=body.AddComponent<CapsuleCollider>();collider.bounds=new Bounds(new Vector3(0,1,0),new Vector3(1,2,1));var zombie=body.AddComponent<ZombieAI>();Assert(!(bool)Call(zombie,"CanReachPlayer"),"Zombie reached through ceiling");playerCollider.bounds=new Bounds(new Vector3(0,1,1),new Vector3(1,2,1));Assert((bool)Call(zombie,"CanReachPlayer"),"Same-level player unexpectedly unreachable");});
 Test("Zombie death reports to the wave only once",()=>{var m=new Match();var zombie=new GameObject("Zombie").AddComponent<ZombieAI>();zombie.InitializeForRound(1,m.Rounds);Set(m.Rounds,"waveStarted",true);Set(m.Rounds,"zombiesAlive",1);zombie.TakeDamage(999,true);Assert(zombie.IsDead&&m.Rounds.currentRound==2&&m.Rounds.ZombiesAlive==0,"Lethal hit did not complete the wave");zombie.TakeDamage(999,true);Assert(m.Rounds.currentRound==2&&m.Rounds.ZombiesAlive==0,"Repeated lethal hit reported another death");});
 Test("World setup disables legacy ammo input and provides a replacement at its authored location",()=>{var m=new Match();var oldStation=new GameObject("Authored ammo marker").AddComponent<AmmoStation>();oldStation.transform.position=new Vector3(4,2,6);var original=oldStation.transform.position;var world=m.MakeWorld();Call(world,"Start");var station=UnityEngine.Object.FindObjectsByType<WorldInteraction>(FindObjectsSortMode.None).FirstOrDefault(s=>s.Kind==WorldInteraction.InteractionKind.Ammo&&s.transform.position==original);Assert(!oldStation.enabled&&oldStation.gameObject&&oldStation.transform.position==original&&station!=null&&station.Owner==world,"Authored marker moved or competing E handlers remained");});
 Test("Reduced weapon-motion setting is independent, persistent and installed only once",()=>{var m=new Match();var panel=new GameObject("Options",typeof(RectTransform));var fullscreenObject=new GameObject("Fullscreen",typeof(RectTransform),typeof(UnityEngine.UI.Toggle));fullscreenObject.transform.SetParent(panel.transform,false);var fullscreen=fullscreenObject.GetComponent<UnityEngine.UI.Toggle>();PlayerPrefs.SetInt("opt_full",1);ComfortOptions.Install(fullscreen);ComfortOptions.Install(fullscreen);var row=panel.transform.Find("ComfortMotionOption");Assert(row!=null&&panel.transform.childCount==2,"Comfort control was duplicated or absent");var toggle=row.GetComponent<UnityEngine.UI.Toggle>();Assert(!toggle.isOn,"Default motion preference was reversed");toggle.onValueChanged.Invoke(true);Assert(PlayerPrefs.GetInt("opt_motion",1)==0&&PlayerPrefs.GetInt("opt_full",0)==1,"Reduced motion changed fullscreen or failed to persist");toggle.onValueChanged.Invoke(false);Assert(PlayerPrefs.GetInt("opt_motion",0)==1,"Normal motion preference did not restore");});
 Test("Global B arsenal cannot bypass closed sectors or generator power",()=>{var m=new Match();var world=m.MakeWorld();m.Shop(10000);m.Session.BuyWeaponUpgrade();m.Session.BuyHealthUpgrade();m.Session.BuyQuickReload();Assert(m.Session.Points==10000&&m.Session.WeaponTier==0,"B arsenal bypassed closed districts");world.RestoreProgress(1,false);m.Session.BuyWeaponUpgrade();Assert(m.Session.Points==10000,"Church gate bypassed power requirement");world.RestoreProgress(3,false);m.Session.BuyHealthUpgrade();Assert(m.Session.Points==10000,"Village gate also enabled perks");world.RestoreProgress(3,true);m.Session.BuyWeaponUpgrade();m.Session.BuyHealthUpgrade();m.Session.BuyQuickReload();Assert(m.Session.Points==5000&&m.Session.WeaponTier==1&&m.Session.HealthBonus==50&&m.Session.HasQuickReload,"Powered equipment remained blocked");});
 Test("Unreachable checkpoints are not fabricated and cannot permanently lock the arsenal",()=>{var m=new Match();var world=m.MakeWorld();UnityEngine.AI.NavMesh.NextPathResult=false;Call(world,"Start");Assert(world.HasPlacementError&&world.ProgressionUnavailable&&!world.HasObjectiveLocation,"Failed navigation left a fictitious objective active");Assert(UnityEngine.Object.FindObjectsByType<WorldInteraction>(FindObjectsSortMode.None).Count(station=>station.TryGetService(out _))==0,"An unreachable station was fabricated");m.Shop(10000);m.Session.BuyWeaponUpgrade();m.Session.BuyHealthUpgrade();m.Session.BuyQuickReload();Assert(m.Session.WeaponTier==1&&m.Session.HealthBonus==50&&m.Session.HasQuickReload&&m.Session.Points==5000,"Unavailable objectives permanently blocked progression");});
 Test("Objective moves to a missing perk and ends without a misleading waypoint",()=>{var m=new Match();var world=m.MakeWorld();var arsenal=m.Station(world,WorldInteraction.InteractionKind.WeaponUpgrade,2);var health=m.Station(world,WorldInteraction.InteractionKind.HealthUpgrade,3);var reload=m.Station(world,WorldInteraction.InteractionKind.QuickReload,4);Set(world,"arsenal",arsenal);Set(world,"fortitude",health);Set(world,"quickReload",reload);world.RestoreProgress(7,true);m.Session.ApplySavedProgress(new GameState{weapon_tier=3});Assert(world.HasObjectiveLocation&&world.ObjectivePosition==health.transform.position,"Objective remained on a completed weapon upgrade");m.Session.ApplySavedProgress(new GameState{weapon_tier=3,health_bonus=100});Assert(world.ObjectivePosition==reload.transform.position,"Objective skipped the remaining reload perk");m.Session.ApplySavedProgress(new GameState{weapon_tier=3,health_bonus=100,reload_perk=1});Assert(!world.HasObjectiveLocation&&world.ObjectiveText.Contains("SOBREVIVE"),"Completed equipment left a misleading waypoint");});
 Test("Specialist wave schedule introduces separate roles at rounds two three and five",()=>{
  Func<int,System.Collections.Generic.HashSet<ZombieArchetype>> kinds=r=>new System.Collections.Generic.HashSet<ZombieArchetype>(Enumerable.Range(0,72).Select(i=>ZombieProfiles.Choose(r,i)));
  Assert(kinds(1).SetEquals(new[]{ZombieArchetype.Walker}),"Specialists appeared before their introductory round");
  Assert(kinds(2).Contains(ZombieArchetype.Runner)&&!kinds(2).Contains(ZombieArchetype.Spitter),"Runner introduction was not distinct");
  Assert(kinds(3).Contains(ZombieArchetype.Spitter)&&!kinds(3).Contains(ZombieArchetype.Brute),"Ranged introduction was not distinct");
  Assert(kinds(5).Count==4,"Later waves never mix all four separate roles");
 });
 Test("Enemy profiles have distinct health damage movement and telegraph budgets",()=>{var walker=ZombieProfiles.Get(ZombieArchetype.Walker);var runner=ZombieProfiles.Get(ZombieArchetype.Runner);var brute=ZombieProfiles.Get(ZombieArchetype.Brute);var spit=ZombieProfiles.Get(ZombieArchetype.Spitter);Assert(runner.Speed>walker.Speed*1.5f&&runner.Health<walker.Health,"Runner is only a renamed walker");Assert(brute.Health>=walker.Health*3&&brute.Damage>walker.Damage&&brute.Windup>walker.Windup,"Heavy has no strengths or dodgeable tell");Assert(spit.Cooldown>walker.Cooldown*2,"Ranged role has no separate cadence");});
 Test("Enemy health scaling is bounded and handles invalid saved rounds",()=>{foreach(ZombieArchetype kind in Enum.GetValues(typeof(ZombieArchetype))){Assert(ZombieProfiles.HealthForRound(kind,int.MinValue)==ZombieProfiles.Get(kind).Health,"Invalid negative round inflated health");Assert(ZombieProfiles.HealthForRound(kind,8)>ZombieProfiles.HealthForRound(kind,1),"Health never progresses");Assert(ZombieProfiles.HealthForRound(kind,int.MaxValue)<=35000,"Health curve overflowed");}});
 Test("Headshots use the actual deform head and deal at least five times base damage",()=>{var m=new Match();var zombie=Enemy(m,ZombieArchetype.Walker,true);var rig=zombie.GetComponent<ZombieRagdoll>();Vector3 head=rig.FindBone("Head").position;Assert(zombie.IsHeadHit(head)&&!zombie.IsHeadHit(head-Vector3.up*.6f),"Neck or torso was treated as the head");Assert(m.Gun.headshotMultiplier>=5,"Headshot boost was not applied");zombie.TakeDamage((int)(m.Gun.damage*m.Gun.headshotMultiplier),true);Assert(zombie.IsDead&&rig.IsFalling,"First-round precision shot failed to drop a normal infected");});
 Test("Only the ranged prefab role can launch acid",()=>{var m=new Match();foreach(var kind in new[]{ZombieArchetype.Walker,ZombieArchetype.Runner,ZombieArchetype.Brute})Assert(ZombieProjectile.Launch(Enemy(m,kind),m.Player,Vector3.zero,Vector3.forward*5,24)==null,"A melee role gained the spitter ability");});
 Test("Acid stops at the nearest wall before it can damage a player",()=>{var m=new Match();var spitter=Enemy(m,ZombieArchetype.Spitter);var wall=new GameObject("Wall").AddComponent<BoxCollider>();var body=m.Player.gameObject.AddComponent<BoxCollider>();var shot=ZombieProjectile.Launch(spitter,m.Player,Vector3.zero,Vector3.forward*5,24);Time.deltaTime=.05f;Physics.NextHits=new[]{new RaycastHit{collider=body,distance=.2f},new RaycastHit{collider=wall,distance=.1f}};Call(shot,"Update");Assert(!shot&&m.Player.CurrentHP==100,"Acid ignored a foreground wall");var hit=ZombieProjectile.Launch(spitter,m.Player,Vector3.zero,Vector3.forward*5,24);Physics.NextHits=new[]{new RaycastHit{collider=body,distance=.1f}};Call(hit,"Update");Assert(!hit&&m.Player.CurrentHP==76,"Unobstructed acid did not apply its role damage once");});
 Test("Acid flight freezes during pause and expires without an invisible lingering attack",()=>{var m=new Match();var spitter=Enemy(m,ZombieArchetype.Spitter);var shot=ZombieProjectile.Launch(spitter,m.Player,Vector3.zero,Vector3.forward*5,24);Time.timeScale=0;var start=shot.transform.position;Call(shot,"Update");Assert(shot&&shot.transform.position==start,"Paused projectile continued to move");Assert(ZombieProjectile.Launch(spitter,m.Player,start,Vector3.forward*5,24)==null,"Paused spitter launched another attack");Time.timeScale=1;Time.time=4;Call(shot,"Update");Assert(!shot,"Expired projectile remained dangerous");});
 Test("Sector rules close the map and expand in order at rounds three five and eight",()=>{Assert(!QuarantineRules.Contains(455,580,0)&&QuarantineRules.Contains(445,555,0),"Initial sector is not confined");int church=QuarantineRules.ForRound(0,3);Assert(church==1&&QuarantineRules.Contains(455,580,church)&&!QuarantineRules.Contains(465,520,church),"Church opening leaked the village");int village=QuarantineRules.ForRound(church,5);Assert(village==3&&QuarantineRules.Contains(465,520,village)&&!QuarantineRules.Contains(800,800,village),"Village opening leaked the outer map");int all=QuarantineRules.ForRound(village,8);Assert(all==7&&QuarantineRules.Contains(800,800,all)&&!QuarantineRules.Contains(float.NaN,0,all),"Final opening failed to release finite map positions");});
 Test("Gate colliders and navigation obstacles change together when a district opens",()=>{var m=new Match();var world=m.MakeWorld();Call(world,"Start");var zones=world.GetComponentInChildren<QuarantineZones>();var church=zones.PortalFor(1);var village=zones.PortalFor(2);var outer=zones.PortalFor(4);Assert(church&&village&&outer,"Physical gate set missing");var c=church.GetComponentInParent<BoxCollider>();var n=church.GetComponentInParent<UnityEngine.AI.NavMeshObstacle>();Assert(c.enabled&&n.enabled&&n.carving,"Closed portal is only decorative");world.RestoreProgress(0,false,3);Assert(!c.enabled&&!n.enabled&&village.GetComponentInParent<BoxCollider>().enabled,"Opening church also opened the village");world.RestoreProgress(0,false,5);Assert(!village.GetComponentInParent<BoxCollider>().enabled&&outer.GetComponentInParent<BoxCollider>().enabled,"Village did not retain its outer gates");world.RestoreProgress(0,false,8);Assert(!outer.GetComponentInParent<BoxCollider>().enabled,"Outer gate remained physically closed");});
 Test("Boundary guard returns a player who crosses a still-closed perimeter seam",()=>{var m=new Match();var world=m.MakeWorld();Call(world,"Start");var zones=world.GetComponentInChildren<QuarantineZones>();m.Player.transform.position=world.SafeSpawn+Vector3.forward*20;Call(zones,"LateUpdate");Assert(m.Player.transform.position==world.SafeSpawn,"A closed-zone seam allowed unrestricted roaming");world.RestoreProgress(1,false);Time.time=1;m.Player.transform.position=world.SafeSpawn+Vector3.forward*20;Call(zones,"LateUpdate");Assert(m.Player.transform.position==world.SafeSpawn+Vector3.forward*20,"An opened area still teleported its visitor");});
 Test("Scheduled gate openings do not charge points and are restored before position checks",()=>{var m=new Match();var world=m.MakeWorld();m.Rounds.currentRound=3;Call(world,"Update");Assert(world.UnlockedZones==1&&m.Session.Points==500&&!world.PowerEnabled,"Automatic church opening charged or enabled power");m.Rounds.currentRound=5;Call(world,"Update");Assert(world.UnlockedZones==3&&!world.PowerEnabled,"Automatic village opening enabled its generator");world.RestoreProgress(0,false,8);Assert(world.UnlockedZones==7&&world.IsInsideOpenArea(world.SafeSpawn+Vector3.right*300),"Continuing a later round restored the wrong boundary");});
 Test("Procedural spawn rejects closed districts occupied positions and disconnected paths",()=>{var m=new Match();var world=m.MakeWorld();var template=new GameObject("Enemy template");template.AddComponent<CapsuleCollider>();var spawner=new GameObject("Spawner").AddComponent<ZombieSpawner>();var method=typeof(ZombieSpawner).GetMethod("TryPosition",Private);Func<Vector3,bool> accepts=p=>{object[] args={p,new UnityEngine.AI.NavMeshQueryFilter{areaMask=-1},template,true,Vector3.zero};return (bool)method.Invoke(spawner,args);};Assert(accepts(m.Player.transform.position+Vector3.right*9),"Legal starting-sector point was rejected");Assert(!accepts(m.Player.transform.position+Vector3.forward*20),"Enemy spawned in a closed district");world.RestoreProgress(1,false);Assert(accepts(m.Player.transform.position+Vector3.forward*20),"Opened district never contributed spawns");Assert(!accepts(m.Player.transform.position+Vector3.right*3),"Enemy appeared at arm's length");UnityEngine.AI.NavMesh.NextPathResult=false;Assert(!accepts(m.Player.transform.position+Vector3.right*9),"Disconnected island accepted a spawn");UnityEngine.AI.NavMesh.NextPathResult=true;Physics.NextOccupants=new[]{new GameObject("Crate").AddComponent<BoxCollider>()};Assert(!accepts(m.Player.transform.position+Vector3.right*9),"Occupied geometry accepted a spawn");});
 Test("Spawn discovery uses the whole NavMesh without requiring the three authored points",()=>{var m=new Match();UnityEngine.AI.NavMesh.NextTriangulation=new UnityEngine.AI.NavMeshTriangulation{vertices=new[]{Vector3.zero,Vector3.right,Vector3.forward,Vector3.one},indices=new[]{0,1,2,1,2,3}};var spawner=new GameObject("Spawner").AddComponent<ZombieSpawner>();spawner.zombiePrefab=new GameObject("Fallback template");spawner.spawnPoints=new Transform[0];spawner.BeginRound(3);Assert(spawner.IsConfigured&&spawner.CandidateCount==2,"Spawner still depends on fixed transforms instead of map triangles");});
 Test("A lethal hit disables Animator and releases the actual deform skeleton",()=>{var m=new Match();var zombie=Enemy(m,ZombieArchetype.Brute,true);var animator=zombie.GetComponent<Animator>();var rig=zombie.GetComponent<ZombieRagdoll>();zombie.TakeDamage(99999,true,Vector3.forward);var bodies=zombie.GetComponentsInChildren<Rigidbody>();Assert(zombie.IsDead&&rig.IsFalling&&rig.HasSkeleton&&!animator.enabled,"Death waited upright for an invalid animation state");Assert(bodies.Length==11&&bodies.All(body=>!body.isKinematic&&body.useGravity),"Deform bones were not released into physics");Assert(zombie.GetComponentsInChildren<CapsuleCollider>().Any(c=>c.enabled&&c.gameObject.layer==2),"Corpse physics or bullet exclusion was absent");});
 Test("Missing custom skeleton still falls and only removes the corpse after settling",()=>{var m=new Match();var zombie=Enemy(m,ZombieArchetype.Walker);var rig=zombie.GetComponent<ZombieRagdoll>();var before=zombie.transform.position;zombie.TakeDamage(99999,false);Time.time=.8f;Call(rig,"Update");Assert(rig.IsFalling&&zombie.transform.position.y<before.y&&zombie.gameObject,"Fallback left an upright disappearing pose");Time.time=5;Call(rig,"Update");Assert(zombie.gameObject,"Corpse vanished before its settling lifetime");Time.time=6;Call(rig,"Update");Time.time=7.6f;Call(rig,"Update");Assert(!zombie.gameObject,"Settled corpse never cleaned up");});
 Console.WriteLine($"RESULT {passed} passed, {failed} failed");return failed==0?0:1;
 }
